{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug, had only 15% oral bioavailability in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A dodecyl ester dipeptide (DVAS) showed average 60% oral bioavailability after single oral dosing in healthy volunteers.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Valomaciclovir stearate, a long-chain fatty ester prodrug, achieved >60% oral bioavailability in humans.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a long-chain ester prodrug, had absolute oral bioavailability of 85 ± 15% in children.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "DINCH, a lipophilic dialkyl ester, was almost completely bioavailable in humans.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a GI lipase inhibitor designed for local action with negligible systemic absorption; despite many high-bioavailability long-chain ester analogs, the recognized identity and mechanism place oral bioavailability well below 20%.",
  "evidence_gaps": [
    "No direct orlistat bioavailability record is present in the supplied evidence.",
    "The only sub-20% analog (laninamivir octanoate) is mechanistically and structurally distant.",
    "Most analog records are high-bioavailability esters and would mislead without recognizing the query as orlistat."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

